// Package canonical defines the canonical FHIR R4-based model used internally by Hub Lab.
// All analyzer results are normalized to these types before being delivered to the LIS.
package canonical

import (
	"encoding/json"
	"fmt"
	"time"
)

// ResourceType enumerates the FHIR resource types used.
type ResourceType string

const (
	ResourceTypeDiagnosticReport ResourceType = "DiagnosticReport"
	ResourceTypeObservation      ResourceType = "Observation"
	ResourceTypeSpecimen         ResourceType = "Specimen"
	ResourceTypeServiceRequest   ResourceType = "ServiceRequest"
	ResourceTypePatient          ResourceType = "Patient"
)

// Code represents a coded value (system + code + display).
type Code struct {
	System  string `json:"system"`
	Code    string `json:"code"`
	Display string `json:"display,omitempty"`
}

// Identifier is a business identifier (e.g., sample barcode, order number).
type Identifier struct {
	System string `json:"system,omitempty"`
	Value  string `json:"value"`
}

// Reference is a reference to another resource.
type Reference struct {
	Reference string `json:"reference,omitempty"`
	Type      string `json:"type,omitempty"`
}

// Quantity represents a measured amount with a unit.
type Quantity struct {
	Value float64 `json:"value"`
	Unit  string  `json:"unit"`
	Code  string  `json:"code,omitempty"` // UCUM code
}

// Range represents a numeric range (for reference ranges).
type Range struct {
	Low  *Quantity `json:"low,omitempty"`
	High *Quantity `json:"high,omitempty"`
}

// Patient represents a minimal FHIR Patient resource.
type Patient struct {
	ResourceType ResourceType `json:"resourceType"`
	ID           string       `json:"id,omitempty"`
	Identifier   []Identifier `json:"identifier,omitempty"`
	Name         string       `json:"name,omitempty"`
}

// Specimen represents a FHIR Specimen resource.
type Specimen struct {
	ResourceType ResourceType `json:"resourceType"`
	ID           string       `json:"id,omitempty"`
	Identifier   []Identifier `json:"identifier,omitempty"`
	Type         Code         `json:"type,omitempty"`
	Collection   *struct {
		CollectedDateTime string `json:"collectedDateTime,omitempty"`
	} `json:"collection,omitempty"`
	Subject *Reference `json:"subject,omitempty"`
}

// Observation represents a FHIR Observation resource (a single test result).
type Observation struct {
	ResourceType    ResourceType `json:"resourceType"`
	ID              string       `json:"id,omitempty"`
	Status          string       `json:"status"` // preliminary | final | amended | cancelled
	Code            Code         `json:"code"`   // LOINC code
	Subject         *Reference   `json:"subject,omitempty"`
	Specimen        *Reference   `json:"specimen,omitempty"`
	ValueQuantity   *Quantity    `json:"valueQuantity,omitempty"`
	ValueString     string       `json:"valueString,omitempty"`
	Interpretation  []Code       `json:"interpretation,omitempty"` // e.g., abnormal flags
	ReferenceRange  []ReferenceRange `json:"referenceRange,omitempty"`
	EffectiveDateTime string    `json:"effectiveDateTime,omitempty"`
	Issued          string       `json:"issued,omitempty"`
	Performer       []Reference  `json:"performer,omitempty"`
}

// ReferenceRange represents a reference range for an observation.
type ReferenceRange struct {
	Low  *Quantity `json:"low,omitempty"`
	High *Quantity `json:"high,omitempty"`
	Text string    `json:"text,omitempty"`
}

// DiagnosticReport represents a FHIR DiagnosticReport that groups observations.
type DiagnosticReport struct {
	ResourceType ResourceType `json:"resourceType"`
	ID           string       `json:"id,omitempty"`
	Status       string       `json:"status"` // registered | partial | final | amended | cancelled
	Code         Code         `json:"code"`   // LOINC panel code
	Subject      *Reference   `json:"subject,omitempty"`
	Specimen     []Reference  `json:"specimen,omitempty"`
	Result       []Reference  `json:"result,omitempty"` // references to Observations
	Issued       string       `json:"issued,omitempty"`
	Performer    []Reference  `json:"performer,omitempty"`
	Conclusion   string       `json:"conclusion,omitempty"`
}

// ServiceRequest represents a FHIR ServiceRequest (a test order from the LIS).
type ServiceRequest struct {
	ResourceType ResourceType `json:"resourceType"`
	ID           string       `json:"id,omitempty"`
	Status       string       `json:"status"` // draft | active | completed | revoked
	Intent       string       `json:"intent"` // order | original-order | reflex-order
	Code         Code         `json:"code"`   // LOINC code for the test
	Subject      Reference    `json:"subject"`
	Specimen     []Reference  `json:"specimen,omitempty"`
	Requester    *Reference   `json:"requester,omitempty"`
	AuthoredOn   string       `json:"authoredOn,omitempty"`
	Identifier   []Identifier `json:"identifier,omitempty"`
}

// Bundle is a collection of FHIR resources (used for transactions).
type Bundle struct {
	ResourceType string     `json:"resourceType"` // always "Bundle"
	Type         string     `json:"type"`         // collection | transaction | batch
	Entry        []BundleEntry `json:"entry,omitempty"`
}

// BundleEntry wraps a resource in a bundle.
type BundleEntry struct {
	Resource json.RawMessage `json:"resource"`
}

// --- Constructors ---

// NewPatient creates a minimal Patient resource.
func NewPatient(id string) *Patient {
	return &Patient{
		ResourceType: ResourceTypePatient,
		ID:           id,
		Identifier:   []Identifier{},
	}
}

// NewSpecimen creates a Specimen resource.
func NewSpecimen(id string) *Specimen {
	return &Specimen{
		ResourceType: ResourceTypeSpecimen,
		ID:           id,
		Identifier:   []Identifier{},
	}
}

// NewObservation creates an Observation with the given LOINC code.
func NewObservation(loincCode, loincDisplay string) *Observation {
	now := time.Now().UTC().Format(time.RFC3339)
	return &Observation{
		ResourceType: ResourceTypeObservation,
		Status:       "preliminary",
		Code: Code{
			System:  "http://loinc.org",
			Code:    loincCode,
			Display: loincDisplay,
		},
		Issued: now,
	}
}

// NewDiagnosticReport creates an empty DiagnosticReport.
func NewDiagnosticReport() *DiagnosticReport {
	now := time.Now().UTC().Format(time.RFC3339)
	return &DiagnosticReport{
		ResourceType: ResourceTypeDiagnosticReport,
		Status:       "partial",
		Code: Code{
			System:  "http://loinc.org",
			Code:    "18719-7",
			Display: "Laboratory report",
		},
		Issued: now,
	}
}

// SetValue sets a numeric value with unit on an Observation.
func (o *Observation) SetValue(value float64, unit string) {
	o.ValueQuantity = &Quantity{
		Value: value,
		Unit:  unit,
		Code:  unit,
	}
	o.ValueString = ""
}

// SetValueString sets a text value on an Observation.
func (o *Observation) SetValueString(value string) {
	o.ValueString = value
	o.ValueQuantity = nil
}

// SetInterpretation adds an interpretation flag (e.g., H, L, N, A).
func (o *Observation) SetInterpretation(code, display string) {
	o.Interpretation = append(o.Interpretation, Code{
		System:  "http://terminology.hl7.org/CodeSystem/v3-ObservationInterpretation",
		Code:    code,
		Display: display,
	})
}

// SetReferenceRange sets the reference range for an observation.
func (o *Observation) SetReferenceRange(low, high float64, unit, text string) {
	o.ReferenceRange = []ReferenceRange{
		{
			Low:  &Quantity{Value: low, Unit: unit},
			High: &Quantity{Value: high, Unit: unit},
			Text: text,
		},
	}
}

// Finalize marks an observation as final.
func (o *Observation) Finalize() {
	o.Status = "final"
}

// AddResult adds an observation reference to the diagnostic report.
func (d *DiagnosticReport) AddResult(obs *Observation) {
	d.Result = append(d.Result, Reference{
		Reference: fmt.Sprintf("Observation/%s", obs.ID),
		Type:      "Observation",
	})
}

// Finalize marks a diagnostic report as final.
func (d *DiagnosticReport) Finalize() {
	d.Status = "final"
}

// AddIdentifier adds an identifier to a patient.
func (p *Patient) AddIdentifier(system, value string) {
	p.Identifier = append(p.Identifier, Identifier{System: system, Value: value})
}

// AddIdentifier adds an identifier to a specimen.
func (s *Specimen) AddIdentifier(system, value string) {
	s.Identifier = append(s.Identifier, Identifier{System: system, Value: value})
}

// Package emulators provides an emulator process manager for Hub Lab.
// It can start/stop autoanalyzer and LIS emulator processes as subprocesses,
// and report their status.
package emulators

import (
	"fmt"
	"os"
	"log"
	"os/exec"
	"sync"
	"time"
)

// EmulatorType identifies the type of emulator.
type EmulatorType string

const (
	EmuAutoanalyzer EmulatorType = "autoanalyzer"
	EmuLIS          EmulatorType = "lis"
	EmuResponder    EmulatorType = "responder"
)

// EmulatorStatus represents the current state of an emulator process.
type EmulatorStatus string

const (
	StatusStopped  EmulatorStatus = "stopped"
	StatusStarting EmulatorStatus = "starting"
	StatusRunning  EmulatorStatus = "running"
	StatusError    EmulatorStatus = "error"
)

// EmulatorConfig holds configuration for starting an emulator.
type EmulatorConfig struct {
	Type       EmulatorType `json:"type"`
	Profile    string       `json:"profile,omitempty"`    // Only for autoanalyzer
	Target     string       `json:"target,omitempty"`     // Host:port for autoanalyzer
	Port       int          `json:"port,omitempty"`       // Port for LIS
	Interval   string       `json:"interval,omitempty"`   // e.g., "5s"
	Critical   float64      `json:"critical,omitempty"`   // 0-100
	Count      int          `json:"count,omitempty"`      // 0 = unlimited
}

// EmulatorInfo holds runtime information about an emulator instance.
type EmulatorInfo struct {
	ID        string         `json:"id"`
	Type      EmulatorType   `json:"type"`
	Status    EmulatorStatus `json:"status"`
	Config    EmulatorConfig `json:"config"`
	StartedAt string         `json:"started_at,omitempty"`
	Error     string         `json:"error,omitempty"`
	PID       int            `json:"pid,omitempty"`
	Profile   string         `json:"profile_name,omitempty"`
}

// Manager manages emulator process lifecycles.
type Manager struct {
	mu        sync.Mutex
	emulators map[string]*emulatorInstance
	binDir    string // path to emulator binaries
}

type emulatorInstance struct {
	Info     EmulatorInfo
	cmd      *exec.Cmd
	cancelCh chan struct{}
}

// NewManager creates a new emulator process manager.
func NewManager(binDir string) *Manager {
	return &Manager{
		emulators: make(map[string]*emulatorInstance),
		binDir:    binDir,
	}
}

// Start starts an emulator with the given configuration.
// Returns the emulator ID.
func (m *Manager) Start(cfg EmulatorConfig) (string, error) {
	m.mu.Lock()
	defer m.mu.Unlock()

	id := fmt.Sprintf("emu-%d", time.Now().UnixNano())

	info := EmulatorInfo{
		ID:        id,
		Type:      cfg.Type,
		Status:    StatusStarting,
		Config:    cfg,
		StartedAt: time.Now().Format(time.RFC3339),
	}

	instance := &emulatorInstance{
		Info:     info,
		cancelCh: make(chan struct{}),
	}

	var cmd *exec.Cmd

	switch cfg.Type {
	case EmuAutoanalyzer:
		binPath := m.binDir + "/autoanalyzer-emulator"
		args := []string{
			"--profile", cfg.Profile,
			"--target", cfg.Target,
		}
		if cfg.Interval != "" {
			args = append(args, "--interval", cfg.Interval)
		}
		if cfg.Critical > 0 {
			args = append(args, "--critical", fmt.Sprintf("%.1f", cfg.Critical))
		}
		if cfg.Count > 0 {
			args = append(args, "--count", fmt.Sprintf("%d", cfg.Count))
		}
		cmd = exec.Command(binPath, args...)
		instance.Info.Profile = cfg.Profile

	case EmuLIS:
		binPath := m.binDir + "/lis-emulator"
		port := cfg.Port
		if port == 0 {
			port = 7777
		}
		args := []string{
			"--port", fmt.Sprintf("%d", port),
		}
		cmd = exec.Command(binPath, args...)

	case EmuResponder:
		binPath := m.binDir + "/responder"
		if cfg.Profile == "" {
			return "", fmt.Errorf("profile required for responder")
		}
		listenPort := cfg.Port
		if listenPort == 0 {
			listenPort = 6666
		}
		args := []string{
			"--profile", cfg.Profile,
			"--listen", fmt.Sprintf(":%d", listenPort),
			"--target", cfg.Target,
		}
		if cfg.Critical > 0 {
			args = append(args, "--critical", fmt.Sprintf("%.1f", cfg.Critical))
		}
		cmd = exec.Command(binPath, args...)
		// Fallback: use go run if binary not found
		if _, err := os.Stat(binPath); os.IsNotExist(err) {
			args = append([]string{"run", "./cmd/emulators/responder"}, args...)
			cmd = exec.Command("go", args...)
			// Find backend dir: check EMULATOR_SRC_DIR env, then try common paths
			if srcDir := os.Getenv("EMULATOR_SRC_DIR"); srcDir != "" {
				cmd.Dir = srcDir
			} else {
				for _, dir := range []string{"backend", ".", ".."} {
					if _, err := os.Stat(dir + "/cmd/emulators/responder/main.go"); err == nil {
						cmd.Dir = dir
						break
					}
				}
			}
		}

	default:
		return "", fmt.Errorf("unknown emulator type: %s", cfg.Type)
	}

	instance.cmd = cmd

	// Start the process
	if err := cmd.Start(); err != nil {
		instance.Info.Status = StatusError
		instance.Info.Error = err.Error()
		m.emulators[id] = instance
		return id, fmt.Errorf("failed to start emulator: %w", err)
	}

	instance.Info.Status = StatusRunning
	instance.Info.PID = cmd.Process.Pid
	m.emulators[id] = instance

	// Monitor the process in background
	go m.monitor(id, instance)

	log.Printf("[EmuMgr] Started %s emulator (id=%s, pid=%d)", cfg.Type, id, cmd.Process.Pid)
	return id, nil
}

// Stop stops a running emulator by ID.
func (m *Manager) Stop(id string) error {
	m.mu.Lock()
	instance, ok := m.emulators[id]
	m.mu.Unlock()

	if !ok {
		return fmt.Errorf("emulator %s not found", id)
	}

	if instance.Info.Status != StatusRunning {
		return fmt.Errorf("emulator %s is not running", id)
	}

	// Signal cancel
	close(instance.cancelCh)

	// Kill the process
	if instance.cmd != nil && instance.cmd.Process != nil {
		if err := instance.cmd.Process.Kill(); err != nil {
			log.Printf("[EmuMgr] Error killing emulator %s: %v", id, err)
		}
	}

	m.mu.Lock()
	instance.Info.Status = StatusStopped
	m.mu.Unlock()

	log.Printf("[EmuMgr] Stopped emulator %s", id)
	return nil
}

// Status returns the status of a specific emulator.
func (m *Manager) Status(id string) (EmulatorInfo, bool) {
	m.mu.Lock()
	defer m.mu.Unlock()

	instance, ok := m.emulators[id]
	if !ok {
		return EmulatorInfo{}, false
	}
	return instance.Info, true
}

// List returns all emulator instances.
func (m *Manager) List() []EmulatorInfo {
	m.mu.Lock()
	defer m.mu.Unlock()

	result := make([]EmulatorInfo, 0, len(m.emulators))
	for _, inst := range m.emulators {
		result = append(result, inst.Info)
	}
	return result
}

// ListByType returns emulators of a specific type.
func (m *Manager) ListByType(t EmulatorType) []EmulatorInfo {
	m.mu.Lock()
	defer m.mu.Unlock()

	var result []EmulatorInfo
	for _, inst := range m.emulators {
		if inst.Info.Type == t {
			result = append(result, inst.Info)
		}
	}
	return result
}

// monitor watches a running emulator process.
func (m *Manager) monitor(id string, instance *emulatorInstance) {
	err := instance.cmd.Wait()

	m.mu.Lock()
	defer m.mu.Unlock()

	if err != nil {
		instance.Info.Status = StatusError
		instance.Info.Error = err.Error()
		log.Printf("[EmuMgr] Emulator %s exited with error: %v", id, err)
	} else {
		instance.Info.Status = StatusStopped
		log.Printf("[EmuMgr] Emulator %s completed normally", id)
	}
}

package emulators

import (
	"fmt"
	"math/rand"
	"strings"
	"time"
)

// MessageGenerator generates ASTM or HL7 messages based on a profile.
type MessageGenerator struct {
	profile       *Profile
	msgCounter    int
	sampleCounter int
}

// NewMessageGenerator creates a new generator for the given profile.
func NewMessageGenerator(profile *Profile) *MessageGenerator {
	return &MessageGenerator{
		profile: profile,
	}
}

// NextMessage generates the next message with a new sample ID.
func (g *MessageGenerator) NextMessage(criticalPercent float64) string {
	g.msgCounter++
	g.sampleCounter++

	sampleID := fmt.Sprintf("SIM%04d", g.sampleCounter)

	if g.profile.IsASTM() {
		return g.buildASTM(sampleID, criticalPercent)
	}
	if g.profile.IsHL7() {
		return g.buildHL7(sampleID, criticalPercent)
	}

	// Fallback: try to generate based on message type
	if g.profile.Message.Type == "ASTM" {
		return g.buildASTM(sampleID, criticalPercent)
	}
	return g.buildHL7(sampleID, criticalPercent)
}

// buildASTM generates an ASTM E1394 message.
// Format:
//
//	H|\^&|||Manufacturer|Model|||||||||
//	P|1
//	O|1|SampleID||^^^TestCode|R||timestamp||||||Serum
//	R|1|^^^TestCode|Value|Unit||Flag|||timestamp|...
//	...
//	L|1|N
func (g *MessageGenerator) buildASTM(sampleID string, criticalPercent float64) string {
	var sb strings.Builder
	now := time.Now().Format("20060102150405")
	manufacturer := g.profile.Analyzer.Manufacturer
	model := g.profile.Analyzer.Model

	// Header segment
	sb.WriteString(fmt.Sprintf("H|\\^&|||%s|%s|||||||||\r", manufacturer, model))

	// Patient segment (fictional)
	patientID := fmt.Sprintf("PAT%06d", rand.Intn(999999))
	sb.WriteString(fmt.Sprintf("P|1|%s\r", patientID))

	// Order segment
	testCodes := g.profile.TestCodes()
	firstCode := ""
	if len(testCodes) > 0 {
		firstCode = testCodes[0]
	}
	sb.WriteString(fmt.Sprintf("O|1|%s||^^^%s|R||%s||||||Serum\r",
		sampleID, firstCode, now))

	// Result segments - one per test code
	for i, code := range testCodes {
		mapping, ok := g.profile.Mapping.TestCodes[code]
		if !ok {
			continue
		}
		val := GenerateValue(code, criticalPercent)
		val.Unit = mapping.UCUM
		if val.Unit == "" {
			val.Unit = "N/A"
		}

		sb.WriteString(fmt.Sprintf("R|%d|^^^%s|%v|%s||%s|||%s|SIM\r",
			i+1, code, val.Value, val.Unit, val.Flag, now))
	}

	// Terminator
	sb.WriteString("L|1|N\r")

	return sb.String()
}

// buildHL7 generates an HL7 v2.5 ORU^R01 message.
func (g *MessageGenerator) buildHL7(sampleID string, criticalPercent float64) string {
	var sb strings.Builder
	now := time.Now().Format("20060102150405")
	controlID := fmt.Sprintf("EMU_%d", g.msgCounter)
	sendingApp := g.profile.Analyzer.Manufacturer + "_" + g.profile.Analyzer.Model
	// Replace spaces/special chars
	sendingApp = strings.ReplaceAll(sendingApp, " ", "_")
	if len(sendingApp) > 30 {
		sendingApp = sendingApp[:30]
	}

	patientID := fmt.Sprintf("PAT%06d", rand.Intn(999999))

	// MSH
	sb.WriteString(fmt.Sprintf("MSH|^~\\&|%s|SIM-LAB|LIS|HOSP|%s||ORU^R01|%s|P|2.5|||NE|AL\r",
		sendingApp, now, controlID))

	// PID
	sb.WriteString(fmt.Sprintf("PID|1||%s||SimPatient^Test\r", patientID))

	// PV1
	sb.WriteString("PV1|1|O\r")

	// ORC
	sb.WriteString(fmt.Sprintf("ORC|RE|ORD_%s\r", sampleID))

	// OBR
	sb.WriteString(fmt.Sprintf("OBR|1|ORD_%s|%s|||%s|%s\r",
		sampleID, sampleID, now, now))

	// OBX segments
	testCodes := g.profile.TestCodes()
	for i, code := range testCodes {
		mapping, ok := g.profile.Mapping.TestCodes[code]
		if !ok {
			continue
		}
		val := GenerateValue(code, criticalPercent)
		val.Unit = mapping.UCUM
		if val.Unit == "" {
			val.Unit = "N/A"
		}
		loinc := mapping.LOINC
		longName := mapping.LongName
		if longName == "" {
			longName = code
		}

		// OBX|setID|valueType|identifier^text^codingSystem||value|unit||flag|||F|||timestamp
		sb.WriteString(fmt.Sprintf("OBX|%d|NM|%s^%s^LOINC||%v|%s||%s|||F|||%s|SIM\r",
			i+1, loinc, longName, val.Value, val.Unit, val.Flag, now))
	}

	return sb.String()
}

// WrapMLLP wraps a message in MLLP framing: <VT> message <FS><CR>
func WrapMLLP(msg string) []byte {
	return []byte("\x0b" + msg + "\x1c\r")
}

// Worklist Responder - listens for worklists on an MLLP port and sends back results.
// Simulates an analyzer receiving orders and producing results.
//
// Usage:
//
//	go run ./cmd/emulators/responder --profile profiles/beckman_au480.yml --listen :6666 --target localhost:5555
package main

import (
	"flag"
	"fmt"
	"log"
	"math/rand"
	"net"
	"strings"
	"time"

	"github.com/hub-lab/backend/internal/emulators"
)

func main() {
	profilePath := flag.String("profile", "", "Path to YAML profile")
	listenAddr := flag.String("listen", ":6666", "Port to listen for worklists")
	hubTarget := flag.String("target", "localhost:5555", "Hub Lab MLLP address")
	critical := flag.Float64("critical", 10.0, "Percentage of critical values")
	flag.Parse()

	if *profilePath == "" {
		log.Fatal("--profile required")
	}

	profile, err := emulators.LoadProfile(*profilePath)
	if err != nil {
		log.Fatalf("Load profile: %v", err)
	}

	ln, err := net.Listen("tcp", *listenAddr)
	if err != nil {
		log.Fatalf("Listen %s: %v", *listenAddr, err)
	}
	defer ln.Close()

	gen := emulators.NewMessageGenerator(profile)

	log.Printf("╔══════════════════════════════════════════════╗")
	log.Printf("║  Worklist Responder                          ║")
	log.Printf("╠══════════════════════════════════════════════╣")
	log.Printf("║  Model:    %-32s ║", profile.Analyzer.Model)
	log.Printf("║  Tests:    %-32d ║", len(profile.Mapping.TestCodes))
	log.Printf("║  Listening: %-31s ║", *listenAddr)
	log.Printf("║  Results → %-30s ║", *hubTarget)
	log.Printf("╚══════════════════════════════════════════════╝")
	log.Println("Waiting for worklists...")

	for {
		conn, err := ln.Accept()
		if err != nil {
			log.Printf("Accept: %v", err)
			continue
		}
		go handle(conn, gen, *hubTarget, *critical)
	}
}

func handle(conn net.Conn, gen *emulators.MessageGenerator, target string, criticalPercent float64) {
	defer conn.Close()
	remote := conn.RemoteAddr().String()

	buf := make([]byte, 65536)
	conn.SetReadDeadline(time.Now().Add(30 * time.Second))
	n, err := conn.Read(buf)
	if err != nil {
		log.Printf("[%s] Read error: %v", remote, err)
		return
	}

	data := string(buf[:n])
	// Strip MLLP framing
	data = strings.TrimPrefix(data, "\x0b")
	data = strings.TrimSuffix(data, "\x1c\x0d")

	samples := extractSamples(data)
	log.Printf("[%s] Received worklist — %d samples: %v", remote, len(samples), samples)

	// Send MLLP ACK
	ack := emulators.WrapMLLP("\x06")
	conn.Write(ack)

	// Connect to Hub Lab
	sender := emulators.NewSender(target)
	if err := sender.Connect(); err != nil {
		log.Printf("[%s] Cannot connect to Hub: %v", remote, err)
		return
	}
	defer sender.Close()

	// Send one result per sample
	for _, sampleID := range samples {
		delay := time.Duration(500+rand.Intn(2000)) * time.Millisecond
		time.Sleep(delay)
		msg := gen.NextMessage(criticalPercent)
		log.Printf("[%s] → Hub Lab: %s (%d bytes)", remote, sampleID, len(msg))
		if err := sender.Send(msg); err != nil {
			log.Printf("[%s] Send error: %v", remote, err)
		}
	}
	log.Printf("[%s] Done — %d results sent", remote, len(samples))
}

func extractSamples(data string) []string {
	var ids []string
	seen := map[string]bool{}
	for _, line := range strings.Split(data, "\r") {
		line = strings.TrimSpace(line)
		if strings.HasPrefix(line, "O|") {
			// ASTM order: O|seq|sample_id|...  (sample_id is field 3, index 2)
			parts := strings.Split(line, "|")
			if len(parts) >= 3 && parts[2] != "" {
				if !seen[parts[2]] {
					ids = append(ids, parts[2])
					seen[parts[2]] = true
				}
			}
		} else if strings.HasPrefix(line, "OBR|") {
			// HL7 OBR: OBR|set_id|placer_order_num|filler_order_num|...
			// filler_order_num (field 4, index 3) is the analyzer's sample ID
			// placer_order_num (field 3, index 2) is the LIS order number
			parts := strings.Split(line, "|")
			// Try filler_order_num first, fall back to placer_order_num
			id := ""
			if len(parts) >= 4 && parts[3] != "" {
				id = parts[3]
			} else if len(parts) >= 3 && parts[2] != "" {
				id = parts[2]
			}
			if id != "" && !seen[id] {
				ids = append(ids, id)
				seen[id] = true
			}
		}
	}
	if len(ids) == 0 {
		ids = append(ids, fmt.Sprintf("SIM-%04d", rand.Intn(9999)))
	}
	return ids
}

package worklist

import (
	"bytes"
	"fmt"
	"strings"
	"time"
)

// EmitResult holds the result of sending a worklist to an instrument.
type EmitResult struct {
	Success      bool   `json:"success"`
	Message      string `json:"message"`
	BytesSent    int    `json:"bytes_sent"`
	InstrumentID string `json:"instrument_id"`
	Protocol     string `json:"protocol"`
	RawMessage   string `json:"raw_message,omitempty"`
}

// Emitter generates and sends worklist messages to instruments.
type Emitter struct{}

// NewEmitter creates a new worklist emitter.
func NewEmitter() *Emitter {
	return &Emitter{}
}

// EmitHL7 generates an HL7 v2.5 OML^O21 message for a worklist.
// Reference: IHE PaLM LAW Profile - LAB-28 (Broadcast Mode)
func (e *Emitter) EmitHL7(worklist *Worklist, entries []*Entry, instrumentName string) (*EmitResult, error) {
	if len(entries) == 0 {
		return nil, fmt.Errorf("worklist has no entries")
	}

	var buf bytes.Buffer
	now := time.Now().UTC().Format("20060102150405")

	// MSH - Message Header
	buf.WriteString(fmt.Sprintf("MSH|^~\\&|HubLab|Lab||%s|%s||OML^O21^OML_O21|%s|P|2.5\r",
		instrumentName, now, worklist.ID))

	// PID - Patient Identification (grouped by patient)
	// We iterate entries and emit PID + OBR for each unique patient
	emittedPatients := make(map[string]bool)

	for _, entry := range entries {
		patientKey := entry.PatientID
		if patientKey == "" {
			patientKey = entry.SampleID
		}

		// Only emit PID once per patient
		if !emittedPatients[patientKey] {
			emittedPatients[patientKey] = true
			buf.WriteString(fmt.Sprintf("PID|1||%s||%s|||M||\r",
				escapeHL7(entry.PatientID), escapeHL7(entry.PatientName)))
		}

		// OBR - Observation Request
		buf.WriteString(fmt.Sprintf("OBR|1||%s|%s|||%s|||||||||%s\r",
			escapeHL7(entry.OrderNumber),
			strings.Join(entry.TestCodes, "~"),
			now,
			escapeHL7(entry.SampleID),
		))

		// OBX segments for each test code
		for i, tc := range entry.TestCodes {
			buf.WriteString(fmt.Sprintf("OBX|%d|ST|%s||%s||||||F\r",
				i+1, escapeHL7(tc), escapeHL7(tc)))
		}
	}

	raw := buf.String()
	return &EmitResult{
		Success:      true,
		Message:      "HL7 OML^O21 generated",
		BytesSent:    len(raw),
		InstrumentID: worklist.InstrumentID,
		Protocol:     "HL7",
		RawMessage:   raw,
	}, nil
}

// EmitASTM generates an ASTM E1394 worklist message.
func (e *Emitter) EmitASTM(worklist *Worklist, entries []*Entry, instrumentName string) (*EmitResult, error) {
	if len(entries) == 0 {
		return nil, fmt.Errorf("worklist has no entries")
	}

	var buf bytes.Buffer
	now := time.Now().UTC().Format("20060102150405")

	// ASTM Frame envelope
	buf.WriteByte(0x02) // STX

	// H - Header
	buf.WriteString(fmt.Sprintf("H|\\^&|||%s|HubLab|%s\r", instrumentName, now))

	// P - Patient, O - Order, R - Result entries
	for _, entry := range entries {
		// P - Patient
		buf.WriteString(fmt.Sprintf("P|1||%s||%s|\r",
			escapeASTM(entry.PatientID), escapeASTM(entry.PatientName)))

		// O - Order (one per sample)
		// Use backslash as component separator in ASTM
		escapedCodes := make([]string, len(entry.TestCodes))
		for i, tc := range entry.TestCodes {
			escapedCodes[i] = escapeASTM(tc)
		}
		buf.WriteString(fmt.Sprintf("O|1|%s||^^^%s|R||%s||||||%s\r",
			escapeASTM(entry.SampleID),
			strings.Join(escapedCodes, "\\"),
			now,
			escapeASTM(entry.OrderNumber),
		))
	}

	// L - Terminator
	buf.WriteString(fmt.Sprintf("L|1|N\r"))

	// ETX + checksum
	buf.WriteByte(0x03)

	raw := buf.String()
	return &EmitResult{
		Success:      true,
		Message:      "ASTM worklist generated",
		BytesSent:    len(raw),
		InstrumentID: worklist.InstrumentID,
		Protocol:     "ASTM",
		RawMessage:   raw,
	}, nil
}

// Emit generates the appropriate message based on protocol and returns the result.
func (e *Emitter) Emit(worklist *Worklist, entries []*Entry, instrumentName string, protocol string) (*EmitResult, error) {
	switch strings.ToUpper(protocol) {
	case "HL7", "HL7_2.5", "HL7_2.3":
		return e.EmitHL7(worklist, entries, instrumentName)
	case "ASTM", "ASTM_E1394", "ASTM_E1381":
		return e.EmitASTM(worklist, entries, instrumentName)
	default:
		// Default to HL7
		return e.EmitHL7(worklist, entries, instrumentName)
	}
}

// escapeHL7 escapes special HL7 characters.
func escapeHL7(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\E\\")
	s = strings.ReplaceAll(s, "|", "\\F\\")
	s = strings.ReplaceAll(s, "^", "\\S\\")
	s = strings.ReplaceAll(s, "&", "\\T\\")
	s = strings.ReplaceAll(s, "~", "\\R\\")
	return s
}

// escapeASTM escapes special ASTM characters.
func escapeASTM(s string) string {
	s = strings.ReplaceAll(s, "\\", "\\\\")
	s = strings.ReplaceAll(s, "|", "\\F\\")
	s = strings.ReplaceAll(s, "^", "\\S\\")
	s = strings.ReplaceAll(s, "&", "\\T\\")
	return s
}

