// Package mapping implements the engine that converts extracted data into
// canonical FHIR resources using LOINC codes and UCUM unit conversions.
package mapping

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/hub-lab/backend/internal/core/engine/template"
	"github.com/hub-lab/backend/pkg/canonical"
)

// Mapper converts extracted analyzer data to canonical FHIR resources.
type Mapper struct {
	profile *template.Profile
}

// NewMapper creates a new mapper for the given profile.
func NewMapper(p *template.Profile) *Mapper {
	return &Mapper{profile: p}
}

// MapObservation converts a single extracted result into a canonical Observation.
func (m *Mapper) MapObservation(data *template.ExtractedData) (*canonical.Observation, error) {
	testCode := data.TestCode
	tc := m.profile.Mapping.GetTestMapping(testCode)
	if tc == nil {
		// Fallback: use test code as-is
		tc = &template.TestCodeMapping{
			LOINC:    testCode,
			LongName: testCode,
			UCUM:     data.Unit,
		}
	}

	obs := canonical.NewObservation(tc.LOINC, tc.LongName)

	// Set value
	if data.Value != "" {
		if val, err := strconv.ParseFloat(data.Value, 64); err == nil {
			unit := data.Unit
			if unit == "" {
				unit = tc.UCUM
			}
			// Apply unit conversion if needed
			converted, convertedUnit, err := m.convertUnit(val, unit, tc.UCUM)
			if err == nil {
				obs.SetValue(converted, convertedUnit)
			} else {
				obs.SetValue(val, unit)
			}
		} else {
			// Non-numeric value (e.g., "Positive", "Yellow")
			obs.SetValueString(data.Value)
		}
	}

	// Set interpretation (abnormal flag)
	if data.AbnormalFlag != "" {
		obs.SetInterpretation(data.AbnormalFlag, m.interpretFlag(data.AbnormalFlag))
	}

	// Set effective date/time
	if data.DateTime != "" {
		obs.EffectiveDateTime = data.DateTime
	}

	// Mark as final if status indicates
	if data.ResultStatus == "F" || data.ResultStatus == "final" {
		obs.Finalize()
	}

	return obs, nil
}

// MapToReport converts a set of extracted results into a DiagnosticReport.
func (m *Mapper) MapToReport(results []*template.ExtractedData, sampleID string) (*canonical.DiagnosticReport, error) {
	report := canonical.NewDiagnosticReport()

	if sampleID != "" {
		specimen := canonical.NewSpecimen(sampleID)
		specimen.AddIdentifier("http://hub-lab/specimen", sampleID)
		report.Specimen = append(report.Specimen, canonical.Reference{
			Reference: fmt.Sprintf("Specimen/%s", specimen.ID),
			Type:      "Specimen",
		})
	}

	for i, data := range results {
		obs, err := m.MapObservation(data)
		if err != nil {
			return nil, fmt.Errorf("mapping result %d: %w", i+1, err)
		}
		obs.ID = fmt.Sprintf("obs-%s-%d", sampleID, i+1)
		report.AddResult(obs)
	}

	report.Finalize()
	return report, nil
}

// convertUnit converts a value from one unit to another if they differ.
func (m *Mapper) convertUnit(value float64, sourceUnit, targetUnit string) (float64, string, error) {
	if sourceUnit == targetUnit {
		return value, sourceUnit, nil
	}

	// Check profile's default conversion
	conv := m.profile.Mapping.DefaultUnitConversion
	if conv != nil && conv.SourceUnit == sourceUnit && conv.TargetUnit == targetUnit {
		return value * conv.Factor, targetUnit, nil
	}

	// Common conversions
	factor, err := getConversionFactor(sourceUnit, targetUnit)
	if err != nil {
		return value, sourceUnit, err
	}
	return value * factor, targetUnit, nil
}

// interpretFlag converts an abnormal flag code to human-readable text.
func (m *Mapper) interpretFlag(flag string) string {
	switch strings.ToUpper(flag) {
	case "N":
		return "Normal"
	case "H", "HI":
		return "High"
	case "L", "LO":
		return "Low"
	case "A", "AA":
		return "Abnormal"
	case "C":
		return "Critical"
	case "R":
		return "Resistant"
	case "S":
		return "Susceptible"
	default:
		return flag
	}
}

// getConversionFactor returns the conversion factor between common lab units.
func getConversionFactor(source, target string) (float64, error) {
	// Normalize unit strings
	source = strings.TrimSpace(source)
	target = strings.TrimSpace(target)

	if source == target {
		return 1.0, nil
	}

	// Common conversions
	type conversion struct {
		source, target string
		factor         float64
	}

	conversions := []conversion{
		// Glucose
		{"mg/dL", "mmol/L", 0.0555},
		{"mmol/L", "mg/dL", 18.018},
		// Creatinine
		{"mg/dL", "umol/L", 88.42},
		{"umol/L", "mg/dL", 0.0113},
		// Bilirubin
		{"mg/dL", "umol/L", 17.1},
		{"umol/L", "mg/dL", 0.0585},
		// Cholesterol
		{"mg/dL", "mmol/L", 0.02586},
		{"mmol/L", "mg/dL", 38.67},
		// Triglycerides
		{"mg/dL", "mmol/L", 0.01129},
		{"mmol/L", "mg/dL", 88.57},
		// Urea/BUN
		{"mg/dL", "mmol/L", 0.357},
		{"mmol/L", "mg/dL", 2.801},
		// Calcium
		{"mg/dL", "mmol/L", 0.2495},
		{"mmol/L", "mg/dL", 4.008},
		// Sodium, Potassium, Chloride
		{"mmol/L", "mEq/L", 1.0},
		{"mEq/L", "mmol/L", 1.0},
	}

	for _, c := range conversions {
		if c.source == source && c.target == target {
			return c.factor, nil
		}
	}

	return 1.0, fmt.Errorf("no conversion from %s to %s", source, target)
}

