1	package template
2	
3	import (
4		"fmt"
5		"strconv"
6		"strings"
7	
8		"github.com/hub-lab/backend/internal/core/parser/astm"
9		"github.com/hub-lab/backend/internal/core/parser/hl7"
10	)
11	
12	// Extractor extracts fields from parsed messages using profile paths.
13	type Extractor struct {
14		profile *Profile
15	}
16	
17	// NewExtractor creates a new extractor for a profile.
18	func NewExtractor(p *Profile) *Extractor {
19		return &Extractor{profile: p}
20	}
21	
22	// ExtractFromASTM extracts data from an ASTM message using the profile's extraction paths.
23	func (e *Extractor) ExtractFromASTM(msg *astm.Message) (*ExtractedData, error) {
24		data := &ExtractedData{
25			Extra: make(map[string]string),
26		}
27	
28		ext := &e.profile.Extraction
29	
30		// Extract named fields
31		if ext.SampleID != "" {
32			data.SampleID = e.resolveASTMPath(msg, ext.SampleID, "1")
33		}
34		if ext.TestCode != "" {
35			data.TestCode = e.resolveASTMPath(msg, ext.TestCode, "1")
36		}
37		if ext.Value != "" {
38			data.Value = e.resolveASTMPath(msg, ext.Value, "1")
39		}
40		if ext.Unit != "" {
41			data.Unit = e.resolveASTMPath(msg, ext.Unit, "1")
42		}
43		if ext.AbnormalFlag != "" {
44			data.AbnormalFlag = e.resolveASTMPath(msg, ext.AbnormalFlag, "1")
45		}
46		if ext.ResultStatus != "" {
47			data.ResultStatus = e.resolveASTMPath(msg, ext.ResultStatus, "1")
48		}
49		if ext.DateTime != "" {
50			data.DateTime = e.resolveASTMPath(msg, ext.DateTime, "1")
51		}
52		if ext.InstrumentID != "" {
53			data.InstrumentID = e.resolveASTMPath(msg, ext.InstrumentID, "1")
54		}
55	
56		// Extract extra fields
57		for name, path := range ext.Extra {
58			data.Extra[name] = e.resolveASTMPath(msg, path, "1")
59		}
60	
61		// For testCode and value with wildcard *, extract the first match
62		if strings.Contains(ext.TestCode, "*") {
63			data.TestCode = e.resolveASTMPath(msg, ext.TestCode, "1")
64		}
65		if strings.Contains(ext.Value, "*") {
66			data.Value = e.resolveASTMPath(msg, ext.Value, "1")
67		}
68	
69		return data, nil
70	}
71	
72	// ExtractFromHL7 extracts data from an HL7 message using the profile's extraction paths.
73	func (e *Extractor) ExtractFromHL7(msg *hl7.Message) (*ExtractedData, error) {
74		data := &ExtractedData{
75			Extra: make(map[string]string),
76		}
77	
78		ext := &e.profile.Extraction
79	
80		if ext.SampleID != "" {
81			data.SampleID = e.resolveHL7Path(msg, ext.SampleID, 0)
82		}
83		if ext.TestCode != "" {
84			data.TestCode = e.resolveHL7Path(msg, ext.TestCode, 0)
85		}
86		if ext.Value != "" {
87			data.Value = e.resolveHL7Path(msg, ext.Value, 0)
88		}
89		if ext.Unit != "" {
90			data.Unit = e.resolveHL7Path(msg, ext.Unit, 0)
91		}
92		if ext.AbnormalFlag != "" {
93			data.AbnormalFlag = e.resolveHL7Path(msg, ext.AbnormalFlag, 0)
94		}
95		if ext.ResultStatus != "" {
96			data.ResultStatus = e.resolveHL7Path(msg, ext.ResultStatus, 0)
97		}
98		if ext.DateTime != "" {
99			data.DateTime = e.resolveHL7Path(msg, ext.DateTime, 0)
100		}
101		if ext.InstrumentID != "" {
102			data.InstrumentID = e.resolveHL7Path(msg, ext.InstrumentID, 0)
103		}
104	
105		for name, path := range ext.Extra {
106			data.Extra[name] = e.resolveHL7Path(msg, path, 0)
107		}
108	
109		return data, nil
110	}
111	
112	// resolveASTMPath resolves a path expression against an ASTM message.
113	func (e *Extractor) resolveASTMPath(msg *astm.Message, path string, defaultSegIdx string) string {
114		fp, err := ParsePath(path)
115		if err != nil {
116			return ""
117		}
118	
119		segIdx := fp.SegmentIdx
120		if segIdx == "" || segIdx == "*" {
121			segIdx = defaultSegIdx
122		}
123	
124		idx, _ := strconv.Atoi(segIdx)
125	
126		var seg *astm.Segment
127		segType := astm.SegmentType(fp.Segment)
128	
129		if fp.SegmentIdx == "*" {
130			// Wildcard: get first matching segment
131			segs := msg.SegmentsByType(segType)
132			if len(segs) == 0 {
133				return ""
134			}
135			seg = segs[0]
136		} else {
137			// Specific index: get nth segment
138			allSegs := msg.SegmentsByType(segType)
139			if idx < 1 || idx > len(allSegs) {
140				// For single segment lookup, try the standard method
141				seg = msg.SegmentByType(segType)
142			} else {
143				seg = allSegs[idx-1]
144			}
145		}
146	
147		if seg == nil {
148			return ""
149		}
150	
151		// Get field (fp.FieldIdx is 1-based for ASTM too)
152		f := seg.GetField(fp.FieldIdx)
153		if f == nil {
154			return ""
155		}
156	
157		if fp.CompIdx >= 0 {
158			return f.GetComponentValue(fp.CompIdx)
159		}
160		return f.GetFieldValue()
161	}
162	
163	// resolveHL7Path resolves a path expression against an HL7 message.
164	func (e *Extractor) resolveHL7Path(msg *hl7.Message, path string, defaultSegIdx int) string {
165		fp, err := ParsePath(path)
166		if err != nil {
167			return ""
168		}
169	
170		var seg *hl7.Segment
171		segName := fp.Segment
172	
173		if fp.SegmentIdx == "*" {
174			// Wildcard: get first matching segment
175			segs := msg.SegmentsByName(segName)
176			if len(segs) == 0 {
177				return ""
178			}
179			seg = segs[0]
180		} else {
181			segIdx := defaultSegIdx
182			if fp.SegmentIdx != "" {
183				segIdx, _ = strconv.Atoi(fp.SegmentIdx)
184			}
185			allSegs := msg.SegmentsByName(segName)
186			if segIdx < 0 || segIdx >= len(allSegs) {
187				seg = msg.SegmentByName(segName)
188			} else {
189				seg = allSegs[segIdx]
190			}
191		}
192	
193		if seg == nil {
194			return ""
195		}
196	
197		f := seg.GetField(fp.FieldIdx)
198		if f == nil {
199			return ""
200		}
201	
202		if fp.CompIdx >= 0 {
203			return f.GetComponentValue(fp.CompIdx)
204		}
205		return f.GetFieldValue()
206	}
207	
208	// ExtractAllResultsFromASTM extracts all result segments as separate ExtractedData.
209	func (e *Extractor) ExtractAllResultsFromASTM(msg *astm.Message) ([]*ExtractedData, error) {
210		ext := &e.profile.Extraction
211		results := msg.SegmentsByType(astm.SegmentResult)
212		var data []*ExtractedData
213	
214		for i, r := range results {
215			d := &ExtractedData{
216				Extra: make(map[string]string),
217			}
218	
219			// Extract testCode from result segment
220			if ext.TestCode != "" {
221				d.TestCode = extractFromASTMSegment(r, ext.TestCode)
222			}
223			if ext.Value != "" {
224				d.Value = extractFromASTMSegment(r, ext.Value)
225			}
226			if ext.Unit != "" {
227				d.Unit = extractFromASTMSegment(r, ext.Unit)
228			}
229			if ext.AbnormalFlag != "" {
230				d.AbnormalFlag = extractFromASTMSegment(r, ext.AbnormalFlag)
231			}
232			if ext.DateTime != "" {
233				d.DateTime = extractFromASTMSegment(r, ext.DateTime)
234			}
235	
236			// Sample ID comes from the order segment
237			if ext.SampleID != "" {
238				if orderSeg := msg.SegmentByType(astm.SegmentOrder); orderSeg != nil {
239					d.SampleID = extractFromASTMSegment(orderSeg, ext.SampleID)
240				}
241			}
242	
243			_ = i
244			data = append(data, d)
245		}
246	
247		return data, nil
248	}
249	
250	// ExtractAllResultsFromHL7 extracts all OBX segments as separate ExtractedData.
251	func (e *Extractor) ExtractAllResultsFromHL7(msg *hl7.Message) ([]*ExtractedData, error) {
252		ext := &e.profile.Extraction
253		obxList := msg.SegmentsByName(hl7.SegOBX)
254		var data []*ExtractedData
255	
256		// Get common data from OBR and PID
257		var sampleID string
258		if ext.SampleID != "" {
259			// Try OBR first
260			if obr := msg.SegmentByName(hl7.SegOBR); obr != nil {
261				fp, err := ParsePath(ext.SampleID)
262				if err == nil && fp.Segment == hl7.SegOBR {
263					f := obr.GetField(fp.FieldIdx)
264					if f != nil {
265						if fp.CompIdx >= 0 {
266							sampleID = f.GetComponentValue(fp.CompIdx)
267						} else {
268							sampleID = f.GetFieldValue()
269						}
270					}
271				}
272			}
273		}
274	
275		for _, obx := range obxList {
276			d := &ExtractedData{
277				SampleID: sampleID,
278				Extra:    make(map[string]string),
279			}
280	
281			// Extract fields from OBX
282			if ext.TestCode != "" {
283				d.TestCode = extractFromHL7Segment(obx, ext.TestCode)
284			}
285			if ext.Value != "" {
286				d.Value = extractFromHL7Segment(obx, ext.Value)
287			}
288			if ext.Unit != "" {
289				d.Unit = extractFromHL7Segment(obx, ext.Unit)
290			}
291			if ext.AbnormalFlag != "" {
292				d.AbnormalFlag = extractFromHL7Segment(obx, ext.AbnormalFlag)
293			}
294			if ext.DateTime != "" {
295				d.DateTime = extractFromHL7Segment(obx, ext.DateTime)
296			}
