package template

import (
	"fmt"
	"strconv"
	"strings"

	"github.com/hub-lab/backend/internal/core/parser/astm"
	"github.com/hub-lab/backend/internal/core/parser/hl7"
)

// Extractor extracts fields from parsed messages using profile paths.
type Extractor struct {
	profile *Profile
}

// NewExtractor creates a new extractor for a profile.
func NewExtractor(p *Profile) *Extractor {
	return &Extractor{profile: p}
}

// ExtractFromASTM extracts data from an ASTM message using the profile's extraction paths.
func (e *Extractor) ExtractFromASTM(msg *astm.Message) (*ExtractedData, error) {
	data := &ExtractedData{
		Extra: make(map[string]string),
	}

	ext := &e.profile.Extraction

	// Extract named fields
	if ext.SampleID != "" {
		data.SampleID = e.resolveASTMPath(msg, ext.SampleID, "1")
	}
	if ext.TestCode != "" {
		data.TestCode = e.resolveASTMPath(msg, ext.TestCode, "1")
	}
	if ext.Value != "" {
		data.Value = e.resolveASTMPath(msg, ext.Value, "1")
	}
	if ext.Unit != "" {
		data.Unit = e.resolveASTMPath(msg, ext.Unit, "1")
	}
	if ext.AbnormalFlag != "" {
		data.AbnormalFlag = e.resolveASTMPath(msg, ext.AbnormalFlag, "1")
	}
	if ext.ResultStatus != "" {
		data.ResultStatus = e.resolveASTMPath(msg, ext.ResultStatus, "1")
	}
	if ext.DateTime != "" {
		data.DateTime = e.resolveASTMPath(msg, ext.DateTime, "1")
	}
	if ext.InstrumentID != "" {
		data.InstrumentID = e.resolveASTMPath(msg, ext.InstrumentID, "1")
	}

	// Extract extra fields
	for name, path := range ext.Extra {
		data.Extra[name] = e.resolveASTMPath(msg, path, "1")
	}

	// For testCode and value with wildcard *, extract the first match
	if strings.Contains(ext.TestCode, "*") {
		data.TestCode = e.resolveASTMPath(msg, ext.TestCode, "1")
	}
	if strings.Contains(ext.Value, "*") {
		data.Value = e.resolveASTMPath(msg, ext.Value, "1")
	}

	return data, nil
}

// ExtractFromHL7 extracts data from an HL7 message using the profile's extraction paths.
func (e *Extractor) ExtractFromHL7(msg *hl7.Message) (*ExtractedData, error) {
	data := &ExtractedData{
		Extra: make(map[string]string),
	}

	ext := &e.profile.Extraction

	if ext.SampleID != "" {
		data.SampleID = e.resolveHL7Path(msg, ext.SampleID, 0)
	}
	if ext.TestCode != "" {
		data.TestCode = e.resolveHL7Path(msg, ext.TestCode, 0)
	}
	if ext.Value != "" {
		data.Value = e.resolveHL7Path(msg, ext.Value, 0)
	}
	if ext.Unit != "" {
		data.Unit = e.resolveHL7Path(msg, ext.Unit, 0)
	}
	if ext.AbnormalFlag != "" {
		data.AbnormalFlag = e.resolveHL7Path(msg, ext.AbnormalFlag, 0)
	}
	if ext.ResultStatus != "" {
		data.ResultStatus = e.resolveHL7Path(msg, ext.ResultStatus, 0)
	}
	if ext.DateTime != "" {
		data.DateTime = e.resolveHL7Path(msg, ext.DateTime, 0)
	}
	if ext.InstrumentID != "" {
		data.InstrumentID = e.resolveHL7Path(msg, ext.InstrumentID, 0)
	}

	for name, path := range ext.Extra {
		data.Extra[name] = e.resolveHL7Path(msg, path, 0)
	}

	return data, nil
}

// resolveASTMPath resolves a path expression against an ASTM message.
func (e *Extractor) resolveASTMPath(msg *astm.Message, path string, defaultSegIdx string) string {
	fp, err := ParsePath(path)
	if err != nil {
		return ""
	}

	segIdx := fp.SegmentIdx
	if segIdx == "" || segIdx == "*" {
		segIdx = defaultSegIdx
	}

	idx, _ := strconv.Atoi(segIdx)

	var seg *astm.Segment
	segType := astm.SegmentType(fp.Segment)

	if fp.SegmentIdx == "*" {
		// Wildcard: get first matching segment
		segs := msg.SegmentsByType(segType)
		if len(segs) == 0 {
			return ""
		}
		seg = segs[0]
	} else {
		// Specific index: get nth segment
		allSegs := msg.SegmentsByType(segType)
		if idx < 1 || idx > len(allSegs) {
			// For single segment lookup, try the standard method
			seg = msg.SegmentByType(segType)
		} else {
			seg = allSegs[idx-1]
		}
	}

	if seg == nil {
		return ""
	}

	// Get field (fp.FieldIdx is 1-based for ASTM too)
	f := seg.GetField(fp.FieldIdx)
	if f == nil {
		return ""
	}

	if fp.CompIdx >= 0 {
		return f.GetComponentValue(fp.CompIdx)
	}
	return f.GetFieldValue()
}

// resolveHL7Path resolves a path expression against an HL7 message.
func (e *Extractor) resolveHL7Path(msg *hl7.Message, path string, defaultSegIdx int) string {
	fp, err := ParsePath(path)
	if err != nil {
		return ""
	}

	var seg *hl7.Segment
	segName := fp.Segment

	if fp.SegmentIdx == "*" {
		// Wildcard: get first matching segment
		segs := msg.SegmentsByName(segName)
		if len(segs) == 0 {
			return ""
		}
		seg = segs[0]
	} else {
		segIdx := defaultSegIdx
		if fp.SegmentIdx != "" {
			segIdx, _ = strconv.Atoi(fp.SegmentIdx)
		}
		allSegs := msg.SegmentsByName(segName)
		if segIdx < 0 || segIdx >= len(allSegs) {
			seg = msg.SegmentByName(segName)
		} else {
			seg = allSegs[segIdx]
		}
	}

	if seg == nil {
		return ""
	}

	f := seg.GetField(fp.FieldIdx)
	if f == nil {
		return ""
	}

	if fp.CompIdx >= 0 {
		return f.GetComponentValue(fp.CompIdx)
	}
	return f.GetFieldValue()
}

// ExtractAllResultsFromASTM extracts all result segments as separate ExtractedData.
func (e *Extractor) ExtractAllResultsFromASTM(msg *astm.Message) ([]*ExtractedData, error) {
	ext := &e.profile.Extraction
	results := msg.SegmentsByType(astm.SegmentResult)
	var data []*ExtractedData

	for i, r := range results {
		d := &ExtractedData{
			Extra: make(map[string]string),
		}

		// Extract testCode from result segment
		if ext.TestCode != "" {
			d.TestCode = extractFromASTMSegment(r, ext.TestCode)
		}
		if ext.Value != "" {
			d.Value = extractFromASTMSegment(r, ext.Value)
		}
		if ext.Unit != "" {
			d.Unit = extractFromASTMSegment(r, ext.Unit)
		}
		if ext.AbnormalFlag != "" {
			d.AbnormalFlag = extractFromASTMSegment(r, ext.AbnormalFlag)
		}
		if ext.DateTime != "" {
			d.DateTime = extractFromASTMSegment(r, ext.DateTime)
		}

		// Sample ID comes from the order segment
		if ext.SampleID != "" {
			if orderSeg := msg.SegmentByType(astm.SegmentOrder); orderSeg != nil {
				d.SampleID = extractFromASTMSegment(orderSeg, ext.SampleID)
			}
		}

		_ = i
		data = append(data, d)
	}

	return data, nil
}

// ExtractAllResultsFromHL7 extracts all OBX segments as separate ExtractedData.
func (e *Extractor) ExtractAllResultsFromHL7(msg *hl7.Message) ([]*ExtractedData, error) {
	ext := &e.profile.Extraction
	obxList := msg.SegmentsByName(hl7.SegOBX)
	var data []*ExtractedData

	// Get common data from OBR and PID
	var sampleID string
	if ext.SampleID != "" {
		// Try OBR first
		if obr := msg.SegmentByName(hl7.SegOBR); obr != nil {
			fp, err := ParsePath(ext.SampleID)
			if err == nil && fp.Segment == hl7.SegOBR {
				f := obr.GetField(fp.FieldIdx)
				if f != nil {
					if fp.CompIdx >= 0 {
						sampleID = f.GetComponentValue(fp.CompIdx)
					} else {
						sampleID = f.GetFieldValue()
					}
				}
			}
		}
	}

	for _, obx := range obxList {
		d := &ExtractedData{
			SampleID: sampleID,
			Extra:    make(map[string]string),
		}

		// Extract fields from OBX
		if ext.TestCode != "" {
			d.TestCode = extractFromHL7Segment(obx, ext.TestCode)
		}
		if ext.Value != "" {
			d.Value = extractFromHL7Segment(obx, ext.Value)
		}
		if ext.Unit != "" {
			d.Unit = extractFromHL7Segment(obx, ext.Unit)
		}
		if ext.AbnormalFlag != "" {
			d.AbnormalFlag = extractFromHL7Segment(obx, ext.AbnormalFlag)
		}
		if ext.DateTime != "" {
			d.DateTime = extractFromHL7Segment(obx, ext.DateTime)
		}
		if ext.ResultStatus != "" {
			d.ResultStatus = extractFromHL7Segment(obx, ext.ResultStatus)
		}

		data = append(data, d)
	}

	return data, nil
}

// extractFromASTMSegment extracts a value from an ASTM segment using a path.
func extractFromASTMSegment(seg *astm.Segment, path string) string {
	fp, err := ParsePath(path)
	if err != nil {
		return ""
	}
	// Ignore segment part since we already have the segment
	f := seg.GetField(fp.FieldIdx)
	if f == nil {
		return ""
	}
	if fp.CompIdx >= 0 {
		return f.GetComponentValue(fp.CompIdx)
	}
	return f.GetFieldValue()
}

// extractFromHL7Segment extracts a value from an HL7 segment using a path.
func extractFromHL7Segment(seg *hl7.Segment, path string) string {
	fp, err := ParsePath(path)
	if err != nil {
		return ""
	}
	f := seg.GetField(fp.FieldIdx)
	if f == nil {
		return ""
	}
	if fp.CompIdx >= 0 {
		return f.GetComponentValue(fp.CompIdx)
	}
	return f.GetFieldValue()
}

// ensure imports are used
var _ = fmt.Sprintf
